// Der Vision-Node liefert Freitext, kein garantiertes JSON. Modelle packen
// die Antwort gern in ```json-Zaeune oder stellen einen Satz voran - deshalb
// wird hier der erste geschweifte Block herausgeschnitten, statt blind
// JSON.parse aufzurufen und den Lauf abstuerzen zu lassen.
const raus = [];
for (const eintrag of $input.all()) {
  const roh = eintrag.json.content ?? eintrag.json.text ?? eintrag.json.message?.content ?? '';
  const inhalt = typeof roh === 'string' ? roh : JSON.stringify(roh);

  let karte = {};
  let gelesen = true;
  try {
    const start = inhalt.indexOf('{');
    const ende = inhalt.lastIndexOf('}');
    karte = start >= 0 && ende > start ? JSON.parse(inhalt.slice(start, ende + 1)) : {};
    if (!Object.keys(karte).length) gelesen = false;
  } catch (e) {
    gelesen = false;
  }

  const formular = $('Visitenkarte hochladen').item.json;
  const leer = (w) => (w === null || w === undefined || String(w).trim() === '' || String(w).trim().toLowerCase() === 'null') ? '' : String(w).trim();

  raus.push({
    json: {
      vorname: leer(karte.vorname),
      nachname: leer(karte.nachname),
      position: leer(karte.position),
      firma: leer(karte.firma),
      email: leer(karte.email).toLowerCase(),
      telefon: leer(karte.telefon),
      mobil: leer(karte.mobil),
      strasse: leer(karte.strasse),
      plz: leer(karte.plz),
      ort: leer(karte.ort),
      webseite: leer(karte.webseite),
      messe: leer(formular['Messe']),
      gespraechsnotiz: leer(formular['Gespraechsnotiz']),
      einwilligung: leer(formular['Einwilligung Kontaktaufnahme']),
      erfasst_am: new Date().toLocaleDateString('de-DE'),
      ki_antwort_lesbar: gelesen,
      rohantwort: gelesen ? '' : inhalt.slice(0, 500)
    }
  });
}
return raus;

// Plausibilitaetspruefung, bevor Muell ins CRM wandert. OCR auf Fotos
// verwechselt regelmaessig 0/O, 1/l und rn/m - eine Adresse wie
// "info@rnueller.de" sieht auf dem Bild richtig aus und ist es nicht.
// Deshalb wird hier nicht korrigiert, sondern markiert: lieber 20 Karten
// automatisch und 3 von Hand als 23 halbfalsche Datensaetze.
const raus = [];
for (const eintrag of $input.all()) {
  const k = { ...eintrag.json };
  const maengel = [];

  // Bewusst grober Formcheck - eine strenge RFC-Regex verwirft mehr
  // gueltige Adressen als sie Lesefehler faengt.
  const mailOk = /^[^@\s]+@[^@\s]+\.[a-zA-Z]{2,}$/.test(k.email);
  if (!k.email) maengel.push('keine E-Mail erkannt');
  else if (!mailOk) maengel.push('E-Mail-Format unplausibel: ' + k.email);

  // Telefon auf Ziffern reduzieren und deutsche Schreibweisen (0711...,
  // 0049..., +49...) auf ein einheitliches Format bringen.
  const normalisiere = (nr) => {
    let z = String(nr).replace(/[^0-9+]/g, '');
    if (!z) return '';
    if (z.startsWith('00')) z = '+' + z.slice(2);
    else if (z.startsWith('0')) z = '+49' + z.slice(1);
    else if (!z.startsWith('+')) z = '+49' + z;
    return z;
  };
  k.telefon = normalisiere(k.telefon);
  k.mobil = normalisiere(k.mobil);

  // Ziffernzahl ohne Laendervorwahl: unter 6 ist keine erreichbare Nummer,
  // ueber 15 verstoesst gegen E.164 - beides deutet auf einen Lesefehler.
  const ziffern = (nr) => nr.replace(/\D/g, '').length;
  if (k.telefon && (ziffern(k.telefon) < 8 || ziffern(k.telefon) > 15)) {
    maengel.push('Telefonnummer unplausibel: ' + k.telefon);
    k.telefon = '';
  }
  if (k.mobil && (ziffern(k.mobil) < 8 || ziffern(k.mobil) > 15)) {
    maengel.push('Mobilnummer unplausibel: ' + k.mobil);
    k.mobil = '';
  }

  if (!k.nachname) maengel.push('kein Nachname erkannt');
  if (!k.firma) maengel.push('keine Firma erkannt');
  if (!k.ki_antwort_lesbar) maengel.push('KI-Antwort war kein verwertbares JSON');

  k.name_komplett = [k.vorname, k.nachname].filter(Boolean).join(' ');
  k.maengel = maengel;
  // Fuer die automatische Uebernahme muessen Nachname und eine gueltige
  // Mailadresse stehen - ohne beides waere weder CRM-Eintrag noch
  // Dankes-Mail moeglich.
  k.verwertbar = Boolean(k.nachname) && mailOk;
  raus.push({ json: k });
}
return raus;
